input.command:
mkdir -p src data/icons && cat > Cargo.toml <<'E'
[package]
name = "cosmic-ext-nightlight"
version = "0.1.0"
edition = "2021"
description = "COSMIC panel applet to toggle night light"
license = "GPL-3.0-only"

[dependencies]
libcosmic = { git = "https://github.com/pop-os/libcosmic", default-features = false, features = ["applet", "applet-token", "wayland", "tokio"] }

[profile.release]
lto = "thin"
E
cat > src/main.rs <<'E'
use cosmic::app::{Core, Task};
use cosmic::Element;

const APP_ID: &str = "io.github.cosmic_ext.Nightlight";
const ICON_ON: &str = "io.github.cosmic_ext.Nightlight-on-symbolic";
const ICON_OFF: &str = "io.github.cosmic_ext.Nightlight-off-symbolic";

fn main() -> cosmic::iced::Result {
    cosmic::applet::run::<Nightlight>(())
}

struct Nightlight {
    core: Core,
    enabled: bool,
}

#[derive(Clone, Debug)]
enum Message {
    Toggle,
}

impl cosmic::Application for Nightlight {
    type Executor = cosmic::SingleThreadExecutor;
    type Flags = ();
    type Message = Message;
    const APP_ID: &'static str = APP_ID;

    fn core(&self) -> &Core {
        &self.core
    }

    fn core_mut(&mut self) -> &mut Core {
        &mut self.core
    }

    fn init(core: Core, _flags: Self::Flags) -> (Self, Task<Message>) {
        (Self { core, enabled: false }, Task::none())
    }

    fn update(&mut self, message: Message) -> Task<Message> {
        match message {
            // For now the toggle only flips state in the UI.
            Message::Toggle => self.enabled = !self.enabled,
        }
        Task::none()
    }

    fn view(&self) -> Element<'_, Message> {
        let icon = if self.enabled { ICON_ON } else { ICON_OFF };
        self.core
            .applet
            .icon_button(icon)
            .on_press(Message::Toggle)
            .into()
    }
}
E
cat > data/io.github.cosmic_ext.Nightlight.desktop <<'E'
[Desktop Entry]
Name=Night Light
Comment=Toggle night light from the panel
Type=Application
Exec=cosmic-ext-nightlight
Terminal=false
Categories=COSMIC;
Keywords=COSMIC;night;light;
Icon=io.github.cosmic_ext.Nightlight-on-symbolic
StartupNotify=true
NoDisplay=true
X-CosmicApplet=true
X-CosmicHoverPopup=Auto
X-OverflowPriority=10
E
cat > data/icons/io.github.cosmic_ext.Nightlight-on-symbolic.svg <<'E'
<svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 16 16"><path fill="#bebebe" d="M8 1a7 7 0 1 0 7 7c0-.5-.1-1-.2-1.400A5 5 0 0 1 8.400 1.200C8.300 1.100 8.100 1 8 1z"/></svg>
E
cat > data/icons/io.github.cosmic_ext.Nightlight-off-symbolic.svg <<'E'
<svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 16 16"><path fill="#bebebe" d="M8 1a7 7 0 1 0 7 7c0-.5-.1-1-.2-1.400A5 5 0 0 1 8.400 1.200C8.300 1.100 8.100 1 8 1z" opacity=".4"/><path fill="#bebebe" d="M2 3l1-1 11 11-1 1z"/></svg>
E
cat > justfile <<'E'
name := 'cosmic-ext-nightlight'
appid := 'io.github.cosmic_ext.Nightlight'
prefix := '/usr'
bin-dst := prefix / 'bin' / name
desktop-dst := prefix / 'share/applications' / appid + '.desktop'
icon-dir := prefix / 'share/icons/hicolor/scalable/status'

default: build

build:
    cargo build --release

check:
    cargo clippy --all-targets

clean:
    cargo clean

install:
    install -Dm0755 target/release/{{name}} {{bin-dst}}
    install -Dm0644 data/{{appid}}.desktop {{desktop-dst}}
    install -Dm0644 data/icons/{{appid}}-on-symbolic.svg {{icon-dir}}/{{appid}}-on-symbolic.svg
    install -Dm0644 data/icons/{{appid}}-off-symbolic.svg {{icon-dir}}/{{appid}}-off-symbolic.svg

uninstall:
    rm -f {{bin-dst}} {{desktop-dst}} {{icon-dir}}/{{appid}}-on-symbolic.svg {{icon-dir}}/{{appid}}-off-symbolic.svg
E
echo target >> .gitignore
CARGO_TARGET_DIR=$FERRIVIDE_SCRATCH/t cargo check --offline 2>&1 | tail -30
